<?php
if (!in_array(parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH), ['/', '/index.php'], true)) { http_response_code(404); exit('Not found.'); }
require dirname(__DIR__).'/app/bootstrap.php';initWeb();$page=(string)($_GET['page']??'home');$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??''))){http_response_code(403);throw new DomainException('Your form expired. Refresh and try again.');}
  $action=(string)($_POST['action']??'');
  if($action==='login'){
   $ip=hash('sha256',$_SERVER['REMOTE_ADDR']??'local');$attempt=q('SELECT * FROM attempts WHERE ip_hash=?',[$ip])->fetch();
   if($attempt&&$attempt['failures']>=5&&time()-(int)$attempt['last_at']<900)throw new DomainException('Too many attempts. Try again in 15 minutes.');
   $u=q('SELECT * FROM users WHERE name=?',[trim((string)($_POST['name']??''))])->fetch();
   if(!$u||!password_verify((string)($_POST['password']??''),$u['password_hash'])){q('INSERT INTO attempts VALUES(?,1,?) ON CONFLICT(ip_hash) DO UPDATE SET failures=CASE WHEN last_at<? THEN 1 ELSE failures+1 END,last_at=?',[$ip,time(),time()-900,time()]);throw new DomainException('Username or password not recognized.');}
   q('DELETE FROM attempts WHERE ip_hash=?',[$ip]);session_regenerate_id(true);$_SESSION['user']=$u['id'];redirect('/?page=desk');
  }elseif($action==='logout'){session_destroy();redirect('/');
  }else{
   requireEditor();
   if($action==='article'){
    articleData($_POST);$image=uploadImage($_FILES['image']??[]);$id=saveArticle($_POST);if($image)q('UPDATE articles SET image=? WHERE id=?',[$image,$id]);redirect('/?page=article&id='.$id);
   }elseif($action==='import'){
    $file=$_FILES['csv']??[];if(($file['error']??1)!==UPLOAD_ERR_OK||$file['size']>1048576)throw new DomainException('Upload a CSV file under 1 MB.');$count=importArticles($file['tmp_name']);$notice=$count.' articles imported.';
   }elseif($action==='page'){
    $values=[];foreach(['title'=>200,'keywords'=>300,'heading'=>200,'content'=>20000,'slug'=>100] as $key=>$max){$v=trim((string)($_POST[$key]??''));if(!$v||strlen($v)>$max)throw new DomainException('Complete all page fields within their limits.');$values[]=$v;}
    if(!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$values[4]))throw new DomainException('The URL key must use lowercase words separated by hyphens.');
    $id=(int)($_POST['id']??0);if($id&&!q('SELECT id FROM pages WHERE id=?',[$id])->fetch())throw new DomainException('Page not found.');if(q('SELECT id FROM pages WHERE slug=? AND id<>?',[$values[4],$id])->fetch())throw new DomainException('That URL key is already in use.');
    $image=uploadImage($_FILES['image']??[]);
    if($id)q('UPDATE pages SET title=?,keywords=?,heading=?,content=?,slug=? WHERE id=?',[...$values,$id]);else{q('INSERT INTO pages(title,keywords,heading,content,slug) VALUES(?,?,?,?,?)',$values);$id=(int)db()->lastInsertId();}
    if($image)q('UPDATE pages SET image=? WHERE id=?',[$image,$id]);redirect('/?page=pages');
   }elseif($action==='user'){
    requireAdmin();$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$role=(string)($_POST['role']??'');$password=(string)($_POST['password']??'');
    if($id&&!q('SELECT id FROM users WHERE id=?',[$id])->fetch())throw new DomainException('User not found.');
    if(!preg_match('/^[a-zA-Z0-9._-]{3,60}$/',$name)||!in_array($role,['admin','editor'],true))throw new DomainException('Use a 3–60 character username and a valid role.');
    if((!$id||$password!=='')&&strlen($password)<12)throw new DomainException('New passwords need at least 12 characters.');
    if($id===(int)user()['id']&&$role!=='admin')throw new DomainException('You cannot remove your own administrator role.');
    if(q('SELECT id FROM users WHERE name=? AND id<>?',[$name,$id])->fetch())throw new DomainException('That username is already in use.');
    $image=uploadImage($_FILES['image']??[]);
    if($id){q('UPDATE users SET name=?,role=? WHERE id=?',[$name,$role,$id]);if($password!=='')q('UPDATE users SET password_hash=? WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$id]);}
    else{q('INSERT INTO users(name,password_hash,role) VALUES(?,?,?)',[$name,password_hash($password,PASSWORD_DEFAULT),$role]);$id=(int)db()->lastInsertId();}
    if($image)q('UPDATE users SET image=? WHERE id=?',[$image,$id]);redirect('/?page=users');
   }
  }
 }catch(DomainException $e){$error=$e->getMessage();if(http_response_code()<400)http_response_code(422);}catch(Throwable $e){error_log($e->getMessage());http_response_code(500);$error='Unable to save. Please try again.';}
}
if(in_array($page,['desk','edit','pages','page-edit','import'],true))requireEditor();if(in_array($page,['users','user-edit'],true))requireAdmin();
function imageTag(?string $image,string $class=''):void{if($image)echo '<img class="'.e($class).'" src="/image.php?file='.e($image).'" alt="Uploaded editorial image">';}
function input(string $key,string $label,array $data=[],string $type='text',bool $required=true):void{echo '<label>'.e($label).'<input type="'.e($type).'" name="'.e($key).'" '.($required?'required':'').' value="'.e($type==='password'?'':($_POST[$key]??$data[$key]??'')).'"></label>';}
function articles(string $search=''):array{$direction=($_GET['sort']??'')==='oldest'?'ASC':'DESC';return q('SELECT * FROM articles WHERE title LIKE ? OR author LIKE ? ORDER BY date '.$direction.',id '.$direction,['%'.$search.'%','%'.$search.'%'])->fetchAll();}
