<?php elseif($page==='article'): $a=q('SELECT * FROM articles WHERE id=?',[(int)($_GET['id']??0)])->fetch();if($a):?><article class="article"><p class="eyebrow">THE EDIT / STORIES</p><h1><?=e($a['title'])?></h1><p class="byline">BY <?=e($a['author'])?> · <?=e($a['date'])?></p><?php imageTag($a['image']);?><div class="body-copy"><?=nl2br(e(str_replace('\\n',"\n",$a['content'])))?></div><?php if(user()):?><a class="read-link" href="/?page=edit&id=<?=$a['id']?>">Edit story ↗</a><?php endif;?></article><?php else:http_response_code(404);?><h1>Story not found.</h1><?php endif;?>
<?php elseif($page==='content'): $a=q('SELECT * FROM pages WHERE slug=?',[(string)($_GET['slug']??'')])->fetch();if($a):?><article class="article"><p class="eyebrow"><?=e($a['title'])?></p><h1><?=e($a['heading'])?></h1><?php imageTag($a['image']);?><div class="body-copy"><?=nl2br(e($a['content']))?></div></article><?php else:http_response_code(404);?><h1>Page not found.</h1><?php endif;?>
<?php elseif($page==='widget'):?><section class="article"><p class="eyebrow">THE REUSABLE NEWS WIDGET</p><h1>Fresh from<br><em>the desk.</em></h1><div class="widget"><?php foreach(array_slice(articles(),0,5) as $a):?><a href="/?page=article&id=<?=$a['id']?>"><small><?=e($a['date'])?></small><h3><?=e($a['title'])?> ↗</h3></a><?php endforeach;?></div><p>Also available as <a class="read-link" href="/api.php?type=articles">structured JSON ↗</a></p></section>
<?php elseif($page==='login'):?><section class="login-layout"><div><p class="eyebrow">BEHIND THE BYLINES</p><h1>Good stories<br>start <em>here.</em></h1><p>Your space to write, publish and keep everything in order.</p></div><form method="post" class="panel"><?=csrf()?><input type="hidden" name="action" value="login"><h2>Welcome back.</h2><?php input('name','Username');input('password','Password',[],'password');?><button>Open the desk ↗</button><p class="hint">Local demo. Use the credentials from the setup guide.</p></form></section>
